  text:(selector,value)=>el(selector).textContent=value,integer:String,fmt:x=>String(x??'—'),toast:()=>{},openJob:()=>{},view:()=>{},
  prepareSignalDisplay:()=>{},renderLiveStatus:()=>{},renderStock:()=>{context.rendered=S.data.summary.symbol;}};
