            db.execute('ALTER TABLE universe ADD COLUMN active INTEGER NOT NULL DEFAULT 1')


def decode(row):
    if row is None:
        return None
    result = dict(row)
    for key in ('settings', 'summary'):
        if result.get(key):
            result[key] = json.loads(result[key])
    return result


