    if previous and json.loads(previous[0]).get('last_date','')>value.get('last_date',''):
        return False
    db.execute('INSERT OR REPLACE INTO results VALUES(?,?,?,?,?,?)',(code,mode,job_id,updated,summary,artifact))
    return True

